/**
 * CypherClient — typed wrapper around the cypher Anchor program.
 *
 * Works with the IDL generated by `anchor build`
 * (target/idl/cypher.json). All instruction helpers return a
 * `Transaction` (or send + confirm via the provided provider), so callers
 * (CLI / agent / tests) stay in control of signing and landing.
 */
import {
  Connection,
  Keypair,
  PublicKey,
  SystemProgram,
  Transaction,
  TransactionInstruction,
  ComputeBudgetProgram,
} from "@solana/web3.js";
import {
  ASSOCIATED_TOKEN_PROGRAM_ID,
  TOKEN_PROGRAM_ID,
  getAssociatedTokenAddressSync,
} from "@solana/spl-token";
import { Program, AnchorProvider, Idl, BN } from "@coral-xyz/anchor";
import { readFileSync } from "fs";
import { PROGRAM_ID } from "./config";
import {
  configPda,
  positionPda,
  timelockPda,
  nativeVaultPda,
  vaultAta,
  marinadePdas,
  jupiterEventAuthority,
} from "./pdas";

/**
 * Strategy kinds in the object form Anchor's TS client expects
 * (IDL enum variants). Use STRATEGY.staking / STRATEGY.trading.
 */
export const STRATEGY = {
  none: { none: {} },
  staking: { staking: {} },
  trading: { trading: {} },
} as const;
export type StrategyKind = (typeof STRATEGY)[keyof typeof STRATEGY];

/** CLI/UX helper: 'staking' | 'trading' -> anchor enum object. */
export function strategyFromName(name: string): StrategyKind {
  switch (name.toLowerCase()) {
    case "staking":
      return STRATEGY.staking;
    case "trading":
      return STRATEGY.trading;
    default:
      throw new Error(`Unknown strategy '${name}' (staking|trading)`);
  }
}

export interface StrategyParams {
  /** Staking: min seconds between stakes. Trading: DCA cycle seconds. */
  cycleSecs: number;
  /** Trading: USDC (6dp) deployed per DCA buy. */
  tradeAmountUsdc: number;
  /** Trading: take-profit trigger in bps above entry (0 = off). */
  takeProfitBps: number;
  /** Trading: stop-loss trigger in bps below entry (0 = off). */
  stopLossBps: number;
  /** Trading: flatten+pause drawdown from high-water-mark (0 = off). */
  maxDrawdownBps: number;
  /** Trading: max slippage bps, enforced on-chain against the oracle. */
  slippageBps: number;
}

export interface InitializeArgs {
  admin: PublicKey;
  guardians: [PublicKey, PublicKey, PublicKey];
  marinadeProgram: PublicKey;
  marinadeState: PublicKey;
  msolMint: PublicKey;
  msolTreasury: PublicKey;
  swapProgram: PublicKey;
  usdcMint: PublicKey;
  wsolMint: PublicKey;
  /** Pyth Solana Receiver program that owns accepted oracle accounts. */
  pythReceiverProgram: PublicKey;
  solUsdFeedId: Buffer; // 32 bytes
  maxPriceStalenessSecs: number;
  maxPriceConfBps: number;
  maxSlippageBps: number;
  minDepositLamports: number;
  maxDepositLamports: number;
  maxTradeUsdc: number;
  minStakeLamports: number;
  minReserveLamports: number;
  timelockDelaySecs: number;
}

export type ConfigChange =
  | { setSwapProgram: { program: PublicKey } }
  | {
      setMarinade: {
        program: PublicKey;
        state: PublicKey;
        msolMint: PublicKey;
        treasury: PublicKey;
      };
    }
  | {
      setOracle: {
        receiverProgram: PublicKey;
        feedId: Buffer;
        stalenessSecs: number;
        confBps: number;
      };
    }
  | {
      setRiskBounds: {
        maxSlippageBps: number;
        minDepositLamports: number;
        maxDepositLamports: number;
        maxTradeUsdc: number;
        minStakeLamports: number;
        minReserveLamports: number;
      };
    }
  | { setGuardians: { guardians: [PublicKey, PublicKey, PublicKey] } }
  | { setTimelockDelay: { delaySecs: number } };

export function loadIdl(path = "target/idl/cypher.json"): Idl {
  return JSON.parse(readFileSync(path, "utf8")) as Idl;
}

export function paramsToBN(p: StrategyParams) {
  return {
    cycleSecs: new BN(p.cycleSecs),
    tradeAmountUsdc: new BN(p.tradeAmountUsdc),
    takeProfitBps: p.takeProfitBps,
    stopLossBps: p.stopLossBps,
    maxDrawdownBps: p.maxDrawdownBps,
    slippageBps: p.slippageBps,
  };
}

/** Borsh-encode the Jupiter v6 `route` payload with an EMPTY route plan.
 *
 * Wire format (borsh):
 *   route_plan: Vec<RoutePlanStep>  -> u32 length (0) when empty
 *   in_amount: u64
 *   quoted_out_amount: u64
 *   slippage_bps: u16
 *   platform_fee_bps: u8
 *
 * The on-chain program ignores the quoted price entirely (it enforces an
 * oracle-anchored minimum output), so this exact-input payload is all the
 * mock (and, with a real route plan, Jupiter itself) needs.
 */
export function encodeRouteData(
  inAmount: number | bigint,
  quotedOutAmount: number | bigint,
  slippageBps: number,
  platformFeeBps = 0,
  routePlanBorsh?: Buffer
): Buffer {
  const plan = routePlanBorsh ?? Buffer.from([0, 0, 0, 0]); // empty Vec
  const b = Buffer.concat([
    plan,
    Buffer.alloc(8),
    Buffer.alloc(8),
    Buffer.alloc(2),
    Buffer.alloc(1),
  ]);
  let o = plan.length;
  b.writeBigUInt64LE(BigInt(inAmount), o);
  o += 8;
  b.writeBigUInt64LE(BigInt(quotedOutAmount), o);
  o += 8;
  b.writeUInt16LE(slippageBps, o);
  o += 2;
  b.writeUInt8(platformFeeBps, o);
  return b;
}

export class CypherClient {
  readonly program: Program;
  readonly connection: Connection;

  constructor(provider: AnchorProvider, idl?: Idl) {
    this.program = new Program(idl ?? loadIdl(), provider);
    this.connection = provider.connection;
    const declared = this.program.programId.toBase58();
    if (declared !== PROGRAM_ID.toBase58()) {
      throw new Error(
        `IDL program id ${declared} does not match expected ${PROGRAM_ID.toBase58()} — run 'anchor build' and 'anchor keys sync'`
      );
    }
  }

  // ---------------- PDAs / accounts ----------------

  config = configPda;
  position = positionPda;

  vaultAtas(owner: PublicKey, cfg: { usdcMint: PublicKey; wsolMint: PublicKey; msolMint: PublicKey }) {
    const p = positionPda(owner);
    return {
      position: p,
      usdc: vaultAta(p, cfg.usdcMint),
      wsol: vaultAta(p, cfg.wsolMint),
      msol: vaultAta(p, cfg.msolMint),
    };
  }

  async fetchConfig(): Promise<any> {
    return (this.program.account as any).globalConfig.fetch(configPda());
  }

  async fetchPosition(owner: PublicKey): Promise<any> {
    return (this.program.account as any).userPosition.fetch(positionPda(owner));
  }

  // ---------------- Admin ----------------

  async initialize(args: InitializeArgs, payer: Keypair): Promise<Transaction> {
    const tx = new Transaction().add(
      await this.program.methods
        .initialize(
          args.admin,
          args.guardians,
          args.marinadeProgram,
          args.marinadeState,
          args.msolMint,
          args.msolTreasury,
          args.swapProgram,
          args.usdcMint,
          args.wsolMint,
          args.pythReceiverProgram,
          [...args.solUsdFeedId],
          new BN(args.maxPriceStalenessSecs),
          new BN(args.maxPriceConfBps),
          args.maxSlippageBps,
          new BN(args.minDepositLamports),
          new BN(args.maxDepositLamports),
          new BN(args.maxTradeUsdc),
          new BN(args.minStakeLamports),
          new BN(args.minReserveLamports),
          new BN(args.timelockDelaySecs)
        )
        .accounts({ payer: payer.publicKey, config: configPda() })
        .instruction()
    );
    return tx;
  }

  async proposeConfigChange(admin: PublicKey, change: ConfigChange, nonce: number) {
    return this.program.methods
      .proposeConfigChange(toAnchorConfigChange(change))
      .accounts({ config: configPda(), 
        admin,
        timelockEntry: timelockPda(nonce),
       })
      .transaction();
  }

  async executeConfigChange(admin: PublicKey, nonce: number) {
    return this.program.methods
      .executeConfigChange()
      .accounts({ config: configPda(),  admin, timelockEntry: timelockPda(nonce)  })
      .transaction();
  }

  async cancelConfigChange(admin: PublicKey, nonce: number) {
    return this.program.methods
      .cancelConfigChange()
      .accounts({ config: configPda(),  admin, timelockEntry: timelockPda(nonce)  })
      .transaction();
  }

  proposeAdmin(admin: PublicKey, newAdmin: PublicKey) {
    return this.program.methods
      .proposeAdmin(newAdmin)
      .accounts({ config: configPda(),  admin  })
      .transaction();
  }

  acceptAdmin(pendingAdmin: PublicKey) {
    return this.program.methods
      .acceptAdmin()
      .accounts({ config: configPda(),  pendingAdmin  })
      .transaction();
  }

  guardianPause(authority: PublicKey) {
    return this.program.methods
      .guardianPause()
      .accounts({ config: configPda(),  authority  })
      .transaction();
  }

  guardianResume(admin: PublicKey) {
    return this.program.methods
      .guardianResume()
      .accounts({ config: configPda(),  admin  })
      .transaction();
  }

  // ---------------- User vault ----------------

  async openPosition(owner: PublicKey, strategy: StrategyKind) {
    return this.program.methods
      .openPosition(strategy)
      .accounts({ config: configPda(),  owner  })
      .transaction();
  }

  async depositSol(owner: PublicKey, lamports: number | BN) {
    return this.program.methods
      .depositSol(new BN(lamports.toString()))
      .accounts({ config: configPda(),  owner  })
      .transaction();
  }

  /** Trading-strategy deposit: wraps SOL into the vault WSOL ATA. */
  async depositSolTrading(owner: PublicKey, lamports: number | BN, pythPrice: PublicKey) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    return this.program.methods
      .depositSolTrading(new BN(lamports.toString()))
      .accounts({ config: configPda(), 
        owner,
        pythPrice,
        vaultWsol: getAssociatedTokenAddressSync(cfg.wsolMint, p, true),
        wsolMint: cfg.wsolMint,
       })
      .transaction();
  }

  async depositToken(owner: PublicKey, usdcAmount: number | BN) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    const ownerUsdc = getAssociatedTokenAddressSync(cfg.usdcMint, owner);
    return this.program.methods
      .depositToken(new BN(usdcAmount.toString()))
      .accounts({ config: configPda(), 
        owner,
        usdcMint: cfg.usdcMint,
        vaultUsdc: getAssociatedTokenAddressSync(cfg.usdcMint, p, true),
        ownerUsdc,
       })
      .transaction();
  }

  async withdrawSol(owner: PublicKey, lamports: number | BN) {
    return this.program.methods
      .withdrawSol(new BN(lamports.toString()))
      .accounts({ config: configPda(),  owner  })
      .transaction();
  }

  async withdrawUsdc(owner: PublicKey, amount: number | BN) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    return this.program.methods
      .withdrawUsdc(new BN(amount.toString()))
      .accounts({ config: configPda(), 
        owner,
        usdcMint: cfg.usdcMint,
        vaultUsdc: getAssociatedTokenAddressSync(cfg.usdcMint, p, true),
        destAta: getAssociatedTokenAddressSync(cfg.usdcMint, owner),
       })
      .transaction();
  }

  async withdrawWsol(owner: PublicKey, amount: number | BN) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    return this.program.methods
      .withdrawWsol(new BN(amount.toString()))
      .accounts({ config: configPda(), 
        owner,
        wsolMint: cfg.wsolMint,
        vaultWsol: getAssociatedTokenAddressSync(cfg.wsolMint, p, true),
        destAta: getAssociatedTokenAddressSync(cfg.wsolMint, owner),
       })
      .transaction();
  }

  async startStrategy(owner: PublicKey, strategy: StrategyKind, params: StrategyParams) {
    return this.program.methods
      .startStrategy(strategy, paramsToBN(params))
      .accounts({ config: configPda(),  owner  })
      .transaction();
  }

  stopStrategy(owner: PublicKey) {
    return this.program.methods.stopStrategy().accounts({ config: configPda(),  owner  }).transaction();
  }

  setPaused(owner: PublicKey, paused: boolean) {
    return this.program.methods
      .setPaused(paused)
      .accounts({ config: configPda(),  owner  })
      .transaction();
  }

  /** Instant-unstake mSOL -> SOL via Marinade liquid unstake. */
  async unstakeMsol(owner: PublicKey, msolAmount: number | BN) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    const md = await marinadePdas(cfg.marinadeProgram, cfg.marinadeState);
    return this.program.methods
      .unstakeMsol(new BN(msolAmount.toString()))
      .accounts({ config: configPda(), 
        owner,
        marinadeProgram: cfg.marinadeProgram,
        marinadeState: cfg.marinadeState,
        msolMint: cfg.msolMint,
        liqPoolSolLeg: md.liqPoolSolLeg,
        liqPoolMsolLeg: md.liqPoolMsolLeg,
        treasuryMsol: cfg.msolTreasury,
        vaultMsol: getAssociatedTokenAddressSync(cfg.msolMint, p, true),
       })
      .transaction();
  }

  async closePosition(owner: PublicKey) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    return this.program.methods
      .closePosition()
      .accounts({ config: configPda(), 
        owner,
        vaultUsdc: getAssociatedTokenAddressSync(cfg.usdcMint, p, true),
        vaultWsol: getAssociatedTokenAddressSync(cfg.wsolMint, p, true),
        vaultMsol: getAssociatedTokenAddressSync(cfg.msolMint, p, true),
       })
      .transaction();
  }

  // ---------------- Cranks (permissionless) ----------------

  /**
   * Build the crank_stake transaction (staking strategy).
   * `opts` adds compute-budget / priority-fee instructions — required in
   * practice on mainnet during congestion.
   */
  async crankStake(
    owner: PublicKey,
    opts?: { computeUnits?: number; priorityFeeMicroLamports?: number }
  ) {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    const md = await marinadePdas(cfg.marinadeProgram, cfg.marinadeState);
    const tx = new Transaction();
    if (opts?.computeUnits) {
      tx.add(ComputeBudgetProgram.setComputeUnitLimit({ units: opts.computeUnits }));
    }
    if (opts?.priorityFeeMicroLamports) {
      tx.add(ComputeBudgetProgram.setComputeUnitPrice({ microLamports: opts.priorityFeeMicroLamports }));
    }
    tx.add(await this.program.methods
      .crankStake()
      .accounts({ config: configPda(), 
        owner,
        marinadeProgram: cfg.marinadeProgram,
        marinadeState: cfg.marinadeState,
        msolMint: cfg.msolMint,
        liqPoolSolLeg: md.liqPoolSolLeg,
        liqPoolMsolLeg: md.liqPoolMsolLeg,
        liqPoolMsolLegAuthority: md.liqPoolMsolLegAuthority,
        reservePda: md.reservePda,
        msolMintAuthority: md.msolMintAuthority,
        vaultMsol: getAssociatedTokenAddressSync(cfg.msolMint, p, true),
       })
      .instruction());
    return tx;
  }

  /**
   * Build the crank_trade transaction (trading strategy).
   *
   * The caller supplies the Jupiter route accounts (from the Jupiter Swap
   * API on mainnet, or from the mock layout in tests) and the route
   * payload bytes. The program validates everything: vault ATAs in the
   * right roles, mints whitelisted, event authority genuine, no vault
   * account among route accounts, exact input and oracle-anchored output.
   */
  async crankTrade(
    owner: PublicKey,
    pythPrice: PublicKey,
    swapAccounts: {
      /** userSourceTokenAccount for the Jupiter route */
      srcTa: PublicKey;
      /** userDestinationTokenAccount for the Jupiter route */
      dstTa: PublicKey;
      /** v6 `destinationTokenAccount` slot (dummy = swap program for plain swaps) */
      destinationTokenAccount: PublicKey;
      /** destinationMint for the Jupiter route */
      dstMint: PublicKey;
      /** v6 `platformFeeAccount` slot (dummy; route data must have fee 0) */
      platformFeeAccount: PublicKey;
      /** remaining route accounts (AMM pools etc.), in order */
      routeAccounts: PublicKey[];
    },
    routeData: Buffer,
    opts?: { computeUnits?: number; priorityFeeMicroLamports?: number }
  ): Promise<Transaction> {
    const cfg = await this.fetchConfig();
    const p = positionPda(owner);
    const eventAuthority = jupiterEventAuthority(cfg.swapProgram);
    const tx = new Transaction();

    if (opts?.computeUnits) {
      tx.add(
        ComputeBudgetProgram.setComputeUnitLimit({
          units: opts.computeUnits,
        })
      );
    }
    if (opts?.priorityFeeMicroLamports) {
      tx.add(
        ComputeBudgetProgram.setComputeUnitPrice({
          microLamports: opts.priorityFeeMicroLamports,
        })
      );
    }

    tx.add(await this.program.methods
      .crankTrade(Buffer.from(routeData))
      .accounts({ config: configPda(), 
        owner,
        pythPrice,
        swapProgram: cfg.swapProgram,
        vaultUsdc: getAssociatedTokenAddressSync(cfg.usdcMint, p, true),
        vaultWsol: getAssociatedTokenAddressSync(cfg.wsolMint, p, true),
        jupSrcTa: swapAccounts.srcTa,
        jupDstTa: swapAccounts.dstTa,
        jupDestinationTokenAccount: swapAccounts.destinationTokenAccount,
        jupDstMint: swapAccounts.dstMint,
        jupPlatformFeeAccount: swapAccounts.platformFeeAccount,
        jupEventAuthority: eventAuthority,
        jupProgramAcct: cfg.swapProgram,
       })
      .remainingAccounts(
        swapAccounts.routeAccounts.map((k) => ({
          pubkey: k,
          isSigner: false,
          isWritable: true,
        }))
      )
      .instruction());
    return tx;
  }
}

/** Map the SDK's ConfigChange union to the IDL's enum shape. */
function toAnchorConfigChange(change: ConfigChange): any {
  if ("setSwapProgram" in change) {
    return { setSwapProgram: change.setSwapProgram };
  }
  if ("setMarinade" in change) {
    return { setMarinade: change.setMarinade };
  }
  if ("setOracle" in change) {
    return {
      setOracle: {
        receiverProgram: change.setOracle.receiverProgram,
        feedId: [...change.setOracle.feedId],
        stalenessSecs: new BN(change.setOracle.stalenessSecs),
        confBps: new BN(change.setOracle.confBps),
      },
    };
  }
  if ("setRiskBounds" in change) {
    const r = change.setRiskBounds;
    return {
      setRiskBounds: {
        maxSlippageBps: r.maxSlippageBps,
        minDepositLamports: new BN(r.minDepositLamports),
        maxDepositLamports: new BN(r.maxDepositLamports),
        maxTradeUsdc: new BN(r.maxTradeUsdc),
        minStakeLamports: new BN(r.minStakeLamports),
        minReserveLamports: new BN(r.minReserveLamports),
      },
    };
  }
  if ("setGuardians" in change) {
    return { setGuardians: change.setGuardians };
  }
  return {
    setTimelockDelay: {
      delaySecs: new BN(change.setTimelockDelay.delaySecs),
    },
  };
}

export { SystemProgram, TransactionInstruction, TOKEN_PROGRAM_ID, ASSOCIATED_TOKEN_PROGRAM_ID };
